head.script:
scwin.btn_menuOpen_onclick = function(e) {
	var menuId = "A00001";
	var menuNm = "업무화면1";
	var menuUrl = "/sample/common_link/tabControl_processMsgFrame_WESD-970_(WSQ-4939)_sub1.xml";

	var tabObj = {
		closable : true,
		openAction : "exist",
		label : menuNm
	};

	var contObj = {
		frameMode : "wframePreload",
		scope : true,
		src : menuUrl,
		alwaysDraw : false,
		title : menuNm,
		dataObject : {
			type : "json",
			name : "param",
			data : {}
		}
	};

	tac_layout.addTab(menuId, tabObj, contObj);
};

scwin.checkVal = function() {
	return localStorage.getItem('log1') <= localStorage.getItem('log2');
};
localStorage.removeItem("log1");
localStorage.removeItem("log2");
